#version 330
#extension GL_ARB_separate_shader_objects : require

#include <minecraft:globals.glsl>
#include <temporal:bus_read.glsl>
#include <temporal:hand.glsl>

// Screen-space ambient occlusion: how much of the hemisphere above each pixel is blocked by nearby
// geometry, from the depth buffer. 12 samples in a cosine-weighted hemisphere of TEMPORAL_AO_RADIUS blocks,
// rotated by a 4 x 4 tiled pattern that the next pass (ao_blur) averages away. Output in red: 1 open, 0 closed.
uniform sampler2D MainSampler;
uniform sampler2D DepthSampler;

layout(location = 0) in vec2 texCoord;
layout(location = 0) out vec4 fragColor;

#define TEMPORAL_AO_SAMPLES 12
const float TEMPORAL_AO_RADIUS = 1.2;      // blocks
const float TEMPORAL_AO_MAX_DISTANCE = 64.0;

vec3 temporal_ao_position(TemporalBus bus, vec2 uv) {
    return temporal_view_position(bus, uv, texture(DepthSampler, uv).r);
}

void main() {
    TemporalBus bus = temporal_read_bus(MainSampler);
    float depth = texture(DepthSampler, texCoord).r;
    fragColor = vec4(1.0);
    if (!bus.present || depth <= 0.0 || temporal_is_hand(depth)) {
        return;
    }
    vec3 p = temporal_view_position(bus, texCoord, depth);
    if (length(p) > TEMPORAL_AO_MAX_DISTANCE) {
        return;
    }
    // Normal from the neighbours on the side with the smaller depth step: clean on block edges.
    vec2 texel = 1.0 / vec2(textureSize(DepthSampler, 0));
    vec3 right = temporal_ao_position(bus, texCoord + vec2(texel.x, 0.0)) - p;
    vec3 left = p - temporal_ao_position(bus, texCoord - vec2(texel.x, 0.0));
    vec3 up = temporal_ao_position(bus, texCoord + vec2(0.0, texel.y)) - p;
    vec3 down = p - temporal_ao_position(bus, texCoord - vec2(0.0, texel.y));
    vec3 dx = abs(right.z) < abs(left.z) ? right : left;
    vec3 dy = abs(up.z) < abs(down.z) ? up : down;
    vec3 n = normalize(cross(dx, dy));
    if (dot(n, p) > 0.0) {
        n = -n;
    }
    // A basis around the normal, rotated per pixel by a 4 x 4 pattern.
    ivec2 pixel = ivec2(gl_FragCoord.xy);
    float rotation = (float((pixel.x & 3) * 4 + (pixel.y & 3)) + 0.5) / 16.0 * 6.28318531;
    vec3 helper = abs(n.y) < 0.9 ? vec3(0.0, 1.0, 0.0) : vec3(1.0, 0.0, 0.0);
    vec3 t = normalize(cross(helper, n));
    vec3 b = cross(n, t);
    float open = 0.0;
    for (int i = 0; i < TEMPORAL_AO_SAMPLES; i++) {
        // Points spread over the hemisphere (golden angle), denser near the surface.
        float f = (float(i) + 0.5) / float(TEMPORAL_AO_SAMPLES);
        float a = float(i) * 2.39996323 + rotation;
        float r = sqrt(f);
        vec3 dir = t * (cos(a) * r) + b * (sin(a) * r) + n * sqrt(1.0 - f);
        float scale = mix(0.2, 1.0, f * f);
        vec3 s = p + dir * TEMPORAL_AO_RADIUS * scale;
        vec4 clip = bus.proj * vec4(s, 1.0);
        vec2 uv = clip.xy / clip.w * 0.5 + 0.5;
        float sceneDepth = texture(DepthSampler, uv).r;
        if (sceneDepth <= 0.0 || any(lessThan(uv, vec2(0.0))) || any(greaterThan(uv, vec2(1.0)))
            || temporal_is_hand(sceneDepth)) {
            open += 1.0;
            continue;
        }
        float sceneZ = temporal_view_position(bus, uv, sceneDepth).z;
        // Blocked if the scene there is in front of the sample, and not so far in front that it is unrelated.
        float behind = sceneZ - s.z;
        float range = smoothstep(0.0, 1.0, TEMPORAL_AO_RADIUS / max(abs(p.z - sceneZ), 1e-3));
        open += behind > 0.03 ? 1.0 - range : 1.0;
    }
    float ao = open / float(TEMPORAL_AO_SAMPLES);
    fragColor = vec4(mix(ao, 1.0, smoothstep(0.75, 1.0, length(p) / TEMPORAL_AO_MAX_DISTANCE)), 1.0, 1.0, 1.0);
}

#version 330
#extension GL_ARB_separate_shader_objects : require

#include <temporal:bus_read.glsl>

// Average the occlusion over the 4 x 4 block of the rotation pattern, ignoring neighbours at a different
// depth, so that the occlusion doesn't bleed across the edges of objects.
uniform sampler2D InSampler;      // ao, red
uniform sampler2D MainSampler;
uniform sampler2D DepthSampler;

layout(location = 0) in vec2 texCoord;
layout(location = 0) out vec4 fragColor;

void main() {
    TemporalBus bus = temporal_read_bus(MainSampler);
    ivec2 pixel = ivec2(gl_FragCoord.xy);
    float depth = texelFetch(DepthSampler, pixel, 0).r;
    if (!bus.present || depth <= 0.0) {
        fragColor = vec4(1.0);
        return;
    }
    vec2 size = vec2(textureSize(DepthSampler, 0));
    float z = temporal_view_position(bus, (vec2(pixel) + 0.5) / size, depth).z;
    float sum = 0.0;
    float weights = 0.0;
    for (int y = -2; y < 2; y++) {
        for (int x = -2; x < 2; x++) {
            ivec2 q = pixel + ivec2(x, y);
            float d = texelFetch(DepthSampler, q, 0).r;
            if (d <= 0.0) {
                continue;
            }
            float qz = temporal_view_position(bus, (vec2(q) + 0.5) / size, d).z;
            float w = 1.0 - smoothstep(0.05, 0.25, abs(qz - z) / max(-z, 1.0) * 8.0);
            sum += texelFetch(InSampler, q, 0).r * w;
            weights += w;
        }
    }
    fragColor = vec4(weights > 0.0 ? sum / weights : 1.0, 1.0, 1.0, 1.0);
}

#version 330
#extension GL_ARB_separate_shader_objects : require

#include <minecraft:globals.glsl>
#include <temporal:bus_read.glsl>
#include <temporal:atmosphere.glsl>
#include <temporal:fog.glsl>
#include <temporal:water.glsl>
#include <temporal:light_code.glsl>
#include <temporal:lighting.glsl>
#include <temporal:shadows.glsl>
#include <temporal:hand.glsl>

// The atmosphere: a scattered sky in place of the vanilla one, with the vanilla moon and stars on top,
// and the distance fog of the world and the clouds turned to that sky instead of the flat fog color.
// Opaque terrain is relit first (temporal:lighting.glsl), from the light levels in its alpha.
// Water pixels are tagged in alpha for the water pass: 0.5 for a horizontal surface, 0.25 for a side.
uniform sampler2D InSampler;
uniform sampler2D DepthSampler;
uniform sampler2D LightSampler;
uniform sampler2D AoSampler;       // screen-space ambient occlusion (post/ao, post/ao_blur): 1 open, 0 closed

layout(location = 0) in vec2 texCoord;
layout(location = 0) out vec4 fragColor;

const float TEMPORAL_AO_STRENGTH = 0.7;

void main() {
    ivec2 pixel = ivec2(texCoord * vec2(textureSize(InSampler, 0)));
    vec4 original = texelFetch(InSampler, pixel, 0);

    // Water markers (temporal:water.glsl): a marker pixel takes the vanilla water of its neighbours, and both
    // the marker and the pixel to its right are water.
    float waterData = 0.0;
    bool drawn = texelFetch(DepthSampler, pixel, 0).r > 0.0;
    if (drawn && temporal_is_water_marker(original, pixel.x)) {
        waterData = original.b;
        vec4 right = texelFetch(InSampler, pixel + ivec2(1, 0), 0);
        vec4 left = texelFetch(InSampler, pixel - ivec2(1, 0), 0);
        bool leftIsWater = temporal_is_water_marker(texelFetch(InSampler, pixel - ivec2(2, 0), 0), pixel.x - 2);
        original = leftIsWater ? 0.5 * (left + right) : right;
    } else if ((pixel.x & 1) == 1) {
        vec4 left = texelFetch(InSampler, pixel - ivec2(1, 0), 0);
        if (drawn && temporal_is_water_marker(left, pixel.x - 1)) {
            waterData = left.b;
        }
    }

    vec3 color = original.rgb;
    TemporalBus bus = temporal_read_bus(InSampler);
    bool inAir = bus.present && temporal_in_air(bus);
    float depth = texture(DepthSampler, texCoord).r;
    bool sky = depth <= 0.0;   // reversed depth: nothing drawn here
    // For the sky, a direction: from a point at the far plane. ProjMat includes the view bobbing, a translation
    // of a few hundredths of a block: from a near point (depth 0.5, a tenth of a block away), it swung the
    // direction by degrees at each step, and the sun and the sky jumped around.
    vec3 viewPosition = temporal_view_position(bus, texCoord, sky ? TEMPORAL_SKY_DEPTH : depth);
    vec3 position = bus.viewToWorld * viewPosition;
    vec3 faceNormal = normalize(cross(dFdx(position), dFdy(position)));   // derivatives: before any branch

    if (inAir) {
        float exposure = temporal_unpack_float(texelFetch(LightSampler, ivec2(0, 0), 0));
        vec3 dir = normalize(position);

        vec3 transmittance;
        vec3 skyLinear = temporal_sky(dir, bus.sunDirection, bus.rainBrightness, temporal_altitude(float(CameraBlockPos.y) - CameraOffset.y), transmittance);
        vec3 discLinear = temporal_sun_disc(dir, bus.sunDirection, transmittance, bus.rainBrightness);
        vec3 skyColor = temporal_tonemap(skyLinear * exposure);
        vec3 skyWithSun = temporal_tonemap((skyLinear + discLinear) * exposure);

        if (sky) {
            // The frame was cleared to the fog color: whatever is above it is the moon and the stars.
            color = skyWithSun + max(original.rgb - bus.fogColor, 0.0);
        } else {
            // What the alpha says (temporal:light_code.glsl): translucent in front of the clear color, opaque terrain
            // with its light levels, or anything else opaque. Water over the void has the alpha of the water
            // texture, 180/255; over anything else, the blend makes it meaningless.
            float a = original.a;
            vec2 levels;
            bool terrain = temporal_decode_light(a, levels) && waterData == 0.0;
            bool overClear = waterData > 0.0 ? a < 0.72 : a < 204.5 / 255.0;
            float alpha = overClear ? a : 1.0;
            float cameraY = float(CameraBlockPos.y) - CameraOffset.y;
            if (overClear && waterData == 0.0 && position.y + cameraY > TEMPORAL_CLOUD_BOTTOM) {
                // Clouds: their alpha is their coverage, faded with distance, and the rest is the clear color
                // showing through. Replace that part with the sky, and light the cloud itself.
                vec3 cloud = original.rgb - (1.0 - alpha) * bus.fogColor;   // alpha x the cloud's own color
                cloud *= temporal_cloud_light(dir, bus.sunDirection, bus.rainBrightness,
                                        texelFetch(LightSampler, ivec2(1, 0), 0).rgb, texelFetch(LightSampler, ivec2(2, 0), 0).rgb);
                color = cloud + (1.0 - alpha) * skyWithSun;
            } else {
                // Terrain, water, entities: vanilla mixed the fog color in by `fog`, and where the surface is
                // translucent with nothing behind it (far water), the clear color shows through by 1 - alpha:
                //     original = alpha * mix(surface, fogColor, fog) + (1 - alpha) * fogColor
                // Take the fog color back out and mix the sky in by `amount` instead, at least as much: more haze
                // with distance (aerial perspective), and a softer fade at the edge of the loaded world.
                float fog = temporal_vanilla_fog(bus, position);
                float amount = temporal_fog_amount(bus, position, fog);
                vec3 surface = original.rgb - (1.0 - alpha) * bus.fogColor - alpha * fog * bus.fogColor;
                if (terrain) {
                    // Shadow from the sun by day, the moon by night, only where the surface faces it.
                    vec3 light = bus.sunDirection.y > 0.0 ? bus.sunDirection : -bus.sunDirection;
                    float shadow = 1.0;
                    if (dot(faceNormal, light) > 0.0 && light.y > 0.0) {
                        mat3 worldToView = transpose(bus.viewToWorld);
                        shadow = temporal_screen_shadow(bus, DepthSampler, viewPosition, worldToView * faceNormal, worldToView * light, vec2(pixel));
                    }
                    surface *= temporal_relight(faceNormal, levels, bus.sunDirection, bus.rainBrightness,
                                          texelFetch(LightSampler, ivec2(1, 0), 0).rgb, texelFetch(LightSampler, ivec2(2, 0), 0).rgb, shadow);
                }
                if (!overClear && waterData == 0.0 && !temporal_is_hand(depth)) {
                    // Ambient occlusion darkens opaque surfaces (terrain and entities), on top of vanilla's.
                    surface *= mix(1.0, texelFetch(AoSampler, pixel, 0).r, TEMPORAL_AO_STRENGTH);
                }
                float keep = (1.0 - amount) / max(1.0 - fog, 1e-4);
                color = surface * keep + alpha * amount * skyColor + (1.0 - alpha) * skyWithSun;
            }
        }
    }

    // Paint the bus column over with its neighbour.
    if (pixel.x == 0) {
        color = texelFetch(InSampler, ivec2(1, pixel.y), 0).rgb;
    }
    float tag = !inAir || waterData == 0.0 ? 1.0 : waterData > 0.75 ? 0.5 : 0.25;
    fragColor = vec4(clamp(color, 0.0, 1.0), tag);
}

#version 330
#extension GL_ARB_separate_shader_objects : require

#include <temporal:light_code.glsl>
#include <temporal:hand.glsl>

// Bloom, step 1: the bright parts of the image, into a small target. A pixel glows if it is very bright,
// or if it looks like a light source: bright, saturated (lava, flames, glowstone…), and at full block light,
// read from the light levels opaque terrain writes in alpha. The saturation keeps out what light sources
// light up: sand next to lava is just as bright, but pale.
uniform sampler2D InSampler;     // the image, after the water pass
uniform sampler2D MainSampler;   // minecraft:main, for its alpha
uniform sampler2D DepthSampler;

layout(std140) uniform SamplerInfo {
    vec2 OutSize;
    vec2 InSize;
    vec2 MainSize;
    vec2 DepthSize;
};

layout(location = 0) in vec2 texCoord;
layout(location = 0) out vec4 fragColor;

void main() {
    // Average the glowing part of the source pixels this output pixel covers (about 4 x 4).
    vec2 footprint = InSize / OutSize;
    ivec2 first = ivec2((texCoord - 0.5 / OutSize) * InSize);
    vec3 sum = vec3(0.0);
    for (int y = 0; y < 4; y++) {
        for (int x = 0; x < 4; x++) {
            ivec2 p = first + ivec2(vec2(x, y) * footprint / 4.0);
            if (temporal_is_hand(texelFetch(DepthSampler, p, 0).r)) {
                continue;   // the hand doesn't glow
            }
            vec3 c = texelFetch(InSampler, p, 0).rgb;
            float luminance = dot(c, vec3(0.2126, 0.7152, 0.0722));
            float glow = smoothstep(0.95, 1.0, luminance);   // white things in sunlight only just
            vec2 levels;
            float saturation = (max(c.r, max(c.g, c.b)) - min(c.r, min(c.g, c.b))) / max(max(c.r, max(c.g, c.b)), 1e-3);
            if (temporal_decode_light(texelFetch(MainSampler, p, 0).a, levels) && levels.x > 0.9) {
                glow = max(glow, 1.5 * smoothstep(0.45, 0.8, luminance) * smoothstep(0.35, 0.6, saturation));
            }
            sum += c * glow;
        }
    }
    fragColor = vec4(sum / 16.0, 1.0);
}

#version 330
#extension GL_ARB_separate_shader_objects : require

// A 9-tap Gaussian blur along one direction (BlurConfig, from the post effect's JSON), with a bilinear
// input: each tap reads two texels at once.
uniform sampler2D InSampler;

layout(std140) uniform SamplerInfo {
    vec2 OutSize;
    vec2 InSize;
};

layout(std140) uniform BlurConfig {
    vec2 Direction;
};

layout(location = 0) in vec2 texCoord;
layout(location = 0) out vec4 fragColor;

void main() {
    const float offsets[3] = float[](0.0, 1.3846153846, 3.2307692308);
    const float weights[3] = float[](0.2270270270, 0.3162162162, 0.0702702703);
    vec2 step = Direction / InSize;
    vec3 sum = texture(InSampler, texCoord).rgb * weights[0];
    for (int i = 1; i < 3; i++) {
        sum += texture(InSampler, texCoord + step * offsets[i]).rgb * weights[i];
        sum += texture(InSampler, texCoord - step * offsets[i]).rgb * weights[i];
    }
    fragColor = vec4(sum, 1.0);
}

#version 330
#extension GL_ARB_separate_shader_objects : require

#include <minecraft:globals.glsl>
#include <temporal:bus_read.glsl>

// This frame's camera, for the next frame's TAA (post/taa), into a persistent 32 x 1 target, a float per
// pixel: 0-15 the projection, 16-24 the view rotation (view to world, column-major), 25-27 the camera's
// position in the world, 28 1 if the bus was present.
uniform sampler2D MainSampler;

layout(location = 0) in vec2 texCoord;
layout(location = 0) out vec4 fragColor;

void main() {
    TemporalBus bus = temporal_read_bus(MainSampler);
    int i = int(gl_FragCoord.x);
    vec3 camera = vec3(CameraBlockPos) - CameraOffset;
    float v = 0.0;
    if (i < 16) {
        v = bus.proj[i / 4][i % 4];
    } else if (i < 25) {
        v = bus.viewToWorld[(i - 16) / 3][(i - 16) % 3];
    } else if (i < 28) {
        v = camera[i - 25];
    } else if (i == 28) {
        v = bus.present ? 1.0 : 0.0;
    }
    fragColor = temporal_pack_float(v);
}

#version 330
#extension GL_ARB_separate_shader_objects : require

// The final image: the bloom (two sizes of glow) added on top.
uniform sampler2D InSampler;
uniform sampler2D BloomNearSampler;   // 480 x 270, a tight glow
uniform sampler2D BloomFarSampler;    // 240 x 135, a wide one

layout(location = 0) in vec2 texCoord;
layout(location = 0) out vec4 fragColor;

const float TEMPORAL_BLOOM_STRENGTH = 0.6;

void main() {
    vec3 color = texture(InSampler, texCoord).rgb;
    vec3 bloom = texture(BloomNearSampler, texCoord).rgb + texture(BloomFarSampler, texCoord).rgb;
    // Screen blend: the glow brightens without clipping as hard as an addition.
    color = 1.0 - (1.0 - color) * (1.0 - bloom * TEMPORAL_BLOOM_STRENGTH * 2.0);
    fragColor = vec4(color, 1.0);
}

#version 330
#extension GL_ARB_separate_shader_objects : require

// A plain copy, alpha 1: marks the history as valid (a persistent target starts cleared to transparent black).
uniform sampler2D InSampler;

layout(location = 0) in vec2 texCoord;
layout(location = 0) out vec4 fragColor;

void main() {
    fragColor = vec4(texelFetch(InSampler, ivec2(gl_FragCoord.xy), 0).rgb, 1.0);
}

#version 330
#extension GL_ARB_separate_shader_objects : require

// Half the size: with a bilinear input, one sample at the center of each 2 x 2 block averages it.
uniform sampler2D InSampler;

layout(location = 0) in vec2 texCoord;
layout(location = 0) out vec4 fragColor;

void main() {
    fragColor = vec4(texture(InSampler, texCoord).rgb, 1.0);
}

#version 330
#extension GL_ARB_separate_shader_objects : require

// Full-screen triangle for post passes, shipped with the pack (vanilla renamed its own in 26.4).
layout(location = 0) out vec2 texCoord;

void main() {
    vec2 uv = vec2((gl_VertexIndex << 1) & 2, gl_VertexIndex & 2);
    gl_Position = vec4(uv * 2.0 - 1.0, 0.0, 1.0);
    texCoord = uv;
}

#version 330
#extension GL_ARB_separate_shader_objects : require

#include <minecraft:globals.glsl>
#include <temporal:bus_read.glsl>
#include <temporal:atmosphere.glsl>

// The scene's light, into a 4 x 1 target, once per frame:
//  x = 0: exposure for the sky (a float in 4 bytes): the average sky luminance over a few directions sets
//         how bright the sky is drawn, like a camera's automatic exposure. Bounded, so the night stays dark.
//  x = 1: the color of the sky's ambient light, normalized (its largest channel is 1).
//  x = 2: the color of the direct light reaching the ground, normalized: the sun through the atmosphere by
//         day (orange at sunset), the moon by night.
uniform sampler2D InSampler;

layout(location = 0) in vec2 texCoord;
layout(location = 0) out vec4 fragColor;

vec3 temporal_normalized(vec3 c) {
    return c / max(max(c.r, max(c.g, c.b)), 1e-6);
}

void main() {
    int x = int(gl_FragCoord.x);
    TemporalBus bus = temporal_read_bus(InSampler);
    if (!bus.present) {
        fragColor = x == 0 ? temporal_pack_float(1.0) : vec4(1.0);
        return;
    }
    float altitude = temporal_altitude(float(CameraBlockPos.y) - CameraOffset.y);
    if (x == 2) {
        bool day = bus.sunDirection.y > 0.0;
        vec3 l = day ? bus.sunDirection : -bus.sunDirection;
        vec3 t = temporal_transmittance_to_light(vec3(0.0, TEMPORAL_PLANET_RADIUS + altitude, 0.0), normalize(vec3(l.x, max(l.y, 0.01), l.z)));
        fragColor = vec4(temporal_normalized(day ? t : t * TEMPORAL_MOON_RADIANCE), 1.0);
        return;
    }
    vec3 sum = vec3(0.0);
    vec3 unused;
    sum += temporal_sky(vec3(0.0, 1.0, 0.0), bus.sunDirection, bus.rainBrightness, altitude, unused);
    for (int i = 0; i < 4; i++) {
        float a = float(i) * 0.5 * TEMPORAL_PI;
        sum += temporal_sky(normalize(vec3(cos(a), 0.25, sin(a))), bus.sunDirection, bus.rainBrightness, altitude, unused);
        sum += temporal_sky(normalize(vec3(cos(a), 1.0, sin(a))), bus.sunDirection, bus.rainBrightness, altitude, unused);
    }
    if (x == 1) {
        fragColor = vec4(temporal_normalized(sum), 1.0);
        return;
    }
    float luminance = dot(sum / 9.0, vec3(0.2126, 0.7152, 0.0722));
    fragColor = temporal_pack_float(clamp(TEMPORAL_EXPOSURE_KEY / max(luminance, 1e-6), TEMPORAL_EXPOSURE_MIN, TEMPORAL_EXPOSURE_MAX));
}

#version 330
#extension GL_ARB_separate_shader_objects : require

#include <minecraft:globals.glsl>
#include <temporal:bus_read.glsl>
#include <temporal:hand.glsl>

// Temporal accumulation. Each pixel's position is reprojected into the previous frame (whose camera
// post/camera_store kept), the previous result is read there, clamped to the colors around the pixel in this
// frame (so that what moved or appeared doesn't leave trails), and blended with this frame. It smooths the
// noise of the shadows and the occlusion, and shimmering.
//
// There is no sub-pixel jitter of the projection: core shaders have no frame counter, and Sodium's terrain
// shader not even GameTime. So the edges of still things are not anti-aliased.
uniform sampler2D InSampler;        // this frame
uniform sampler2D HistorySampler;   // the previous result (persistent); alpha 1 where valid
uniform sampler2D PreviousSampler;  // the previous camera (persistent, post/camera_store)
uniform sampler2D MainSampler;
uniform sampler2D DepthSampler;

layout(location = 0) in vec2 texCoord;
layout(location = 0) out vec4 fragColor;

const float TEMPORAL_TAA_BLEND = 0.12;   // share of this frame

float temporal_previous(int i) {
    return temporal_unpack_float(texelFetch(PreviousSampler, ivec2(i, 0), 0));
}

void main() {
    ivec2 pixel = ivec2(gl_FragCoord.xy);
    vec3 current = texelFetch(InSampler, pixel, 0).rgb;
    fragColor = vec4(current, 1.0);
    TemporalBus bus = temporal_read_bus(MainSampler);
    // The hand moves with the camera, not with the world: no history for it.
    if (!bus.present || temporal_previous(28) < 0.5 || temporal_is_hand(texelFetch(DepthSampler, pixel, 0).r)) {
        return;
    }
    mat4 previousProj;
    for (int i = 0; i < 16; i++) {
        previousProj[i / 4][i % 4] = temporal_previous(i);
    }
    mat3 previousViewToWorld;
    for (int i = 0; i < 9; i++) {
        previousViewToWorld[i / 3][i % 3] = temporal_previous(16 + i);
    }
    vec3 previousCamera = vec3(temporal_previous(25), temporal_previous(26), temporal_previous(27));
    vec3 camera = vec3(CameraBlockPos) - CameraOffset;

    float depth = texelFetch(DepthSampler, pixel, 0).r;
    vec3 position = bus.viewToWorld * temporal_view_position(bus, texCoord, depth > 0.0 ? depth : TEMPORAL_SKY_DEPTH);
    // The sky is at infinity: only the rotation counts. Elsewhere, the camera's own movement too.
    vec3 previousView = transpose(previousViewToWorld) * (depth > 0.0 ? position + camera - previousCamera : position);
    vec4 clip = previousProj * vec4(previousView, 1.0);
    vec2 uv = clip.xy / clip.w * 0.5 + 0.5;
    if (clip.w <= 0.0 || any(lessThan(uv, vec2(0.0))) || any(greaterThan(uv, vec2(1.0)))) {
        return;
    }
    vec4 history = texture(HistorySampler, uv);
    if (history.a < 0.5) {
        return;
    }
    // Clamp the history to this frame's 3 x 3 neighbourhood.
    vec3 low = current;
    vec3 high = current;
    for (int y = -1; y <= 1; y++) {
        for (int x = -1; x <= 1; x++) {
            vec3 c = texelFetch(InSampler, pixel + ivec2(x, y), 0).rgb;
            low = min(low, c);
            high = max(high, c);
        }
    }
    fragColor = vec4(mix(clamp(history.rgb, low, high), current, TEMPORAL_TAA_BLEND), 1.0);
}

#version 330
#extension GL_ARB_separate_shader_objects : require

#include <minecraft:globals.glsl>
#include <temporal:bus_read.glsl>
#include <temporal:atmosphere.glsl>
#include <temporal:fog.glsl>
#include <temporal:hand.glsl>

// Water: the surface the atmosphere pass tagged is redrawn with waves, reflections and refraction.
//  - Waves: a sum of directional waves gives the surface's slope at each point (the geometry stays flat).
//  - Reflection: a ray marched in screen space against the depth buffer, else the sky in that direction.
//  - Refraction: the vanilla water (what is underneath, tinted), shifted by the waves.
//  - Fresnel: grazing angles reflect more.
uniform sampler2D InSampler;        // the atmosphere pass's output; alpha tags water (0.5 top, 0.25 side)
uniform sampler2D MainSampler;      // minecraft:main, for the data bus
uniform sampler2D DepthSampler;
uniform sampler2D LightSampler;

layout(location = 0) in vec2 texCoord;
layout(location = 0) out vec4 fragColor;

#define TEMPORAL_SSR_STEPS 40
#define TEMPORAL_WAVE_COUNT 8
const float TEMPORAL_FRESNEL_WAVES = 0.25;   // how much of the waves' tilt Fresnel sees
const float TEMPORAL_REFLECTION_RIPPLE = 0.04;   // how far, in screen units per unit of tilt, the waves shift the mirrored image
const float TEMPORAL_WAVE_STRENGTH = 0.6;   // how much the waves tilt the surface
const float TEMPORAL_WAVE_FLATTEN_DISTANCE = 48.0;   // the waves tilt half as much this far away
const float TEMPORAL_WAVE_GRAZING_STRENGTH = 0.15;   // and this much, at a grazing angle
const vec3 TEMPORAL_WATER_ABSORPTION = vec3(0.30, 0.12, 0.08);

// Smooth value noise in [0, 1], for the irregularity of the waves.
float temporal_noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    vec2 u = f * f * (3.0 - 2.0 * f);
    float a = fract(sin(dot(i, vec2(127.1, 311.7))) * 43758.5453);
    float b = fract(sin(dot(i + vec2(1.0, 0.0), vec2(127.1, 311.7))) * 43758.5453);
    float c = fract(sin(dot(i + vec2(0.0, 1.0), vec2(127.1, 311.7))) * 43758.5453);
    float d = fract(sin(dot(i + vec2(1.0, 1.0), vec2(127.1, 311.7))) * 43758.5453);
    return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

// Height of the surface (blocks), and its gradient, at world position p (x, z) and time t (seconds).
// Deep-water waves: angular frequency sqrt(g k), rounded to a whole number of periods per 1200 s, the
// period of GameTime, so that the waves don't jump when it wraps.
// footprint: the size of a pixel on the surface, in blocks. A wave shorter than a few pixels can't be shown:
// sampled once per pixel, it turns into rings around the camera (moiré). Each wave fades out before that.
// Pure sines repeat: seen from afar, the sea became regular parallel bands. A slow noise bends the wave fronts
// (it shifts the position each wave sees) and varies each wave's amplitude from place to place. The noise
// depends on the position only, so nothing jumps when GameTime wraps; its own slope is left out of the
// gradient, which it barely changes at that scale.
vec3 temporal_waves(vec2 p, float t, float footprint) {
    const vec2 directions[TEMPORAL_WAVE_COUNT] = vec2[](vec2(1.0, 0.3), vec2(-0.4, 1.0), vec2(0.8, -0.7),
                                                  vec2(-1.0, -0.2), vec2(0.2, -1.0), vec2(0.9, 0.9),
                                                  vec2(-0.7, 0.6), vec2(0.4, 0.95));
    const float wavelengths[TEMPORAL_WAVE_COUNT] = float[](7.3, 4.6, 3.1, 2.2, 1.55, 1.1, 0.8, 0.57);
    vec2 warp = (vec2(temporal_noise(p * 0.045), temporal_noise(p * 0.045 + 31.7)) - 0.5) * 14.0;
    vec3 sum = vec3(0.0);
    for (int i = 0; i < TEMPORAL_WAVE_COUNT; i++) {
        vec2 d = normalize(directions[i]);
        float k = 2.0 * TEMPORAL_PI / wavelengths[i];
        float omega = round(sqrt(9.81 * k) * 1200.0 / (2.0 * TEMPORAL_PI)) * 2.0 * TEMPORAL_PI / 1200.0;
        float variation = 0.3 + 1.4 * temporal_noise(p * (0.6 / wavelengths[i] / 8.0) + float(i) * 17.3);
        float amplitude = 0.017 * wavelengths[i] * variation * smoothstep(2.0, 6.0, wavelengths[i] / footprint);
        float phase = k * dot(d, p + warp * (0.5 + 0.1 * float(i))) - omega * t;
        sum += amplitude * vec3(sin(phase), k * cos(phase) * d);
    }
    return sum;
}

float temporal_fresnel(float cosTheta) {
    return 0.02 + 0.98 * pow(1.0 - clamp(cosTheta, 0.0, 1.0), 5.0);
}

// March the reflected ray in view space; on a hit, where on the screen (xy) and how much to trust it (z).
vec3 temporal_screen_space_reflection(TemporalBus bus, vec3 origin, vec3 direction) {
    float stepLength = 0.3 + 0.01 * length(origin);
    vec3 previous = origin;
    vec3 position = origin;
    for (int i = 0; i < TEMPORAL_SSR_STEPS; i++) {
        position += direction * stepLength;
        vec4 clip = bus.proj * vec4(position, 1.0);
        if (clip.w <= 0.0) {
            break;
        }
        vec2 uv = clip.xy / clip.w * 0.5 + 0.5;
        if (any(lessThan(uv, vec2(0.0))) || any(greaterThan(uv, vec2(1.0)))) {
            break;
        }
        float depth = texture(DepthSampler, uv).r;
        if (depth > 0.0 && !temporal_is_hand(depth)) {
            float behind = temporal_view_position(bus, uv, depth).z - position.z;   // > 0: the ray went behind the scene
            if (behind > 0.0 && behind < stepLength * 3.0 + 0.5) {
                // Refine between the last two points.
                vec3 a = previous;
                vec3 b = position;
                for (int j = 0; j < 5; j++) {
                    vec3 m = 0.5 * (a + b);
                    vec4 c = bus.proj * vec4(m, 1.0);
                    vec2 muv = c.xy / c.w * 0.5 + 0.5;
                    float md = texture(DepthSampler, muv).r;
                    if (md > 0.0 && temporal_view_position(bus, muv, md).z > m.z) {
                        b = m;
                        uv = muv;
                    } else {
                        a = m;
                    }
                }
                vec2 edge = smoothstep(vec2(0.0), vec2(0.08), min(uv, 1.0 - uv));
                float trust = edge.x * edge.y * (1.0 - float(i) / float(TEMPORAL_SSR_STEPS));
                return vec3(uv, trust);
            }
        }
        previous = position;
        stepLength *= 1.12;
    }
    return vec3(0.0);
}

void main() {
    vec4 color = texture(InSampler, texCoord);
    TemporalBus bus = temporal_read_bus(MainSampler);
    float depth = texture(DepthSampler, texCoord).r;
    vec3 viewPosition = temporal_view_position(bus, texCoord, max(depth, 1e-6));
    vec3 position = bus.viewToWorld * viewPosition;
    vec3 faceNormal = normalize(cross(dFdx(position), dFdy(position)));   // derivatives: before any branch
    fragColor = vec4(color.rgb, 1.0);
    if (color.a > 0.9 || !bus.present) {
        return;   // not water, or the atmosphere pass was inactive
    }
    bool top = color.a > 0.375;
    float exposure = temporal_unpack_float(texelFetch(LightSampler, ivec2(0, 0), 0));
    vec3 cameraPosition = vec3(CameraBlockPos) - CameraOffset;
    vec3 view = normalize(position);
    float dist = length(position);

    // Surface normal: waves on horizontal surfaces.
    if (dot(faceNormal, view) > 0.0) {
        faceNormal = -faceNormal;
    }
    vec3 normal = faceNormal;
    if (top) {
        // A pixel's size on the water: its angular size times the distance, stretched at grazing angles.
        float footprint = dist * 2.0 / (bus.proj[1][1] * ScreenSize.y) / max(abs(view.y), 0.05);
        vec3 wave = temporal_waves((position + cameraPosition).xz, GameTime * 1200.0, footprint);
        // At a grazing angle, even a small tilt sends the reflection to the sky: the sea stops mirroring the
        // land behind it. So the waves tilt less the flatter the view, and also with distance.
        float grazing = mix(TEMPORAL_WAVE_GRAZING_STRENGTH, 1.0, smoothstep(0.02, 0.25, abs(view.y)));
        float strength = TEMPORAL_WAVE_STRENGTH * grazing / (1.0 + dist / TEMPORAL_WAVE_FLATTEN_DISTANCE);
        normal = normalize(vec3(-wave.y * strength, 1.0, -wave.z * strength));
        if (faceNormal.y < 0.0) {
            normal.y = -normal.y;   // seen from below
        }
    }

    // Reflection: the screen first, the sky where the ray leaves it.
    vec3 reflected = reflect(view, normal);
    if (top && reflected.y * normal.y < 0.0) {
        reflected.y = -reflected.y;   // a steep wave can't reflect into the water
    }
    float altitude = temporal_altitude(cameraPosition.y);
    vec3 transmittance;
    vec3 skyLinear = temporal_sky(reflected, bus.sunDirection, bus.rainBrightness, altitude, transmittance);
    // The sun's glint: its disc, and a wider lobe for the small waves the normal can't show.
    float glint = pow(max(dot(reflected, bus.sunDirection), 0.0), 600.0) * 2.0;
    skyLinear += temporal_sun_disc(reflected, bus.sunDirection, transmittance, bus.rainBrightness)
               + TEMPORAL_SUN_RADIANCE * transmittance * glint * bus.rainBrightness;
    vec3 reflection = temporal_tonemap(skyLinear * exposure);
    vec3 viewNormal = mat3(transpose(bus.viewToWorld)) * normal;
    // The screen is searched along the reflection of the flat surface, and the waves only shift where its
    // color is read. Searched along the waves' own reflection, a grazing ray hit the land or missed it
    // depending on the slightest tilt, and the sea stopped mirroring what stands behind it.
    mat3 worldToView = mat3(transpose(bus.viewToWorld));
    vec3 viewFace = worldToView * faceNormal;
    vec3 hit = temporal_screen_space_reflection(bus, viewPosition + viewFace * 0.05, worldToView * reflect(view, faceNormal));
    if (hit.z > 0.0) {
        vec2 ripple = (viewNormal.xy - viewFace.xy) * TEMPORAL_REFLECTION_RIPPLE;
        vec2 uv = hit.xy + ripple;
        vec4 there = texture(InSampler, uv);
        // Keep the shifted read if it lands on screen and not on the water itself.
        vec3 mirrored = there.a > 0.9 && all(greaterThan(uv, vec2(0.0))) && all(lessThan(uv, vec2(1.0)))
                      ? there.rgb : texture(InSampler, hit.xy).rgb;
        reflection = mix(reflection, mirrored, hit.z);
    }

    // Distance fog on the reflection, as on everything else (the refraction already has it).
    vec3 unused;
    vec3 skyAlongView = temporal_tonemap(temporal_sky(view, bus.sunDirection, bus.rainBrightness, altitude, unused) * exposure);
    float fogAmount = temporal_fog_amount(bus, position, temporal_vanilla_fog(bus, position));
    reflection = mix(reflection, skyAlongView, fogAmount);

    // Refraction: the vanilla water, shifted by the waves, if the shifted pixel is still water.
    vec2 shifted = texCoord + (viewNormal.xy - (mat3(transpose(bus.viewToWorld)) * faceNormal).xy) * 0.03;
    vec4 under = texture(InSampler, shifted);
    vec3 refraction = under.a < 0.9 ? under.rgb : color.rgb;
    // Absorption: the seabed's depth is unknown (water writes its own depth), but at grazing angles light
    // crosses more water, so the refraction darkens toward blue-green with the angle. Not the part that is
    // already fog.
    float path = 1.0 / max(dot(-view, faceNormal), 0.15);
    refraction = mix(refraction * exp(-TEMPORAL_WATER_ABSORPTION * path), refraction, fogAmount);

    // At a grazing angle, Fresnel swings from 0.8 to 0.3 with a slight tilt: with the waves' full normal, the
    // reflection gave way to the water's blue. The waves only take part in it a little.
    float fresnel = temporal_fresnel(dot(-view, normalize(mix(faceNormal, normal, TEMPORAL_FRESNEL_WAVES))));
    fragColor = vec4(mix(refraction, reflection, fresnel), 1.0);
}

#ifndef TEMPORAL_ATMOSPHERE_GLSL
#define TEMPORAL_ATMOSPHERE_GLSL

// Sky from single scattering in an Earth-like atmosphere: Rayleigh scattering (air molecules, the blue
// sky), Mie scattering (aerosols, the glow around the sun) and ozone absorption (the deep blue of
// twilight). Ray-marched per pixel, in meters, with the planet's center below the camera.
// Coefficients: Bruneton & Neyret 2008, Hillaire 2020.

#define TEMPORAL_VIEW_STEPS 16
#define TEMPORAL_LIGHT_STEPS 4

const float TEMPORAL_PI = 3.14159265;
const float TEMPORAL_PLANET_RADIUS = 6360e3;
const float TEMPORAL_ATMOSPHERE_RADIUS = 6460e3;
const vec3 TEMPORAL_RAYLEIGH_SCATTERING = vec3(5.802e-6, 13.558e-6, 33.1e-6);
const float TEMPORAL_MIE_SCATTERING = 3.996e-6;
const float TEMPORAL_MIE_EXTINCTION = 4.440e-6;
const float TEMPORAL_MIE_G = 0.8;
const vec3 TEMPORAL_OZONE_ABSORPTION = vec3(0.650e-6, 1.881e-6, 0.085e-6);

const vec3 TEMPORAL_SUN_RADIANCE = vec3(20.0);
const vec3 TEMPORAL_MOON_RADIANCE = vec3(0.020, 0.024, 0.032);   // dimmer and slightly blue: night vision
const vec3 TEMPORAL_NIGHT_GLOW = vec3(0.0006, 0.0008, 0.0016);   // airglow and starlight, so night is never black
// Automatic exposure (post/exposure): exposure = key / average sky luminance, within these bounds.
const float TEMPORAL_EXPOSURE_KEY = 0.28;
const float TEMPORAL_EXPOSURE_MIN = 0.05;
const float TEMPORAL_EXPOSURE_MAX = 30.0;
// Distance, in blocks, over which the haze of the air covers about 63% of what is behind it.
const float TEMPORAL_HAZE_DISTANCE = 900.0;

// Translucent pixels above this height are clouds (the overworld's cloud_height is 192.33).
const float TEMPORAL_CLOUD_BOTTOM = 190.0;

const float TEMPORAL_SUN_COS_RADIUS = 0.99985;                    // about 1 degree: bigger than the real sun, reads better

// Density of air, aerosols and ozone at height h, relative to sea level.
vec3 temporal_density(float h) {
    return vec3(exp(-h / 8000.0), exp(-h / 1200.0), max(0.0, 1.0 - abs(h - 25000.0) / 15000.0));
}

vec3 temporal_extinction(vec3 opticalDepth) {
    return TEMPORAL_RAYLEIGH_SCATTERING * opticalDepth.x + TEMPORAL_MIE_EXTINCTION * opticalDepth.y + TEMPORAL_OZONE_ABSORPTION * opticalDepth.z;
}

// Distance from o (inside the sphere) to where the ray leaves the sphere of radius r centered on the origin.
float temporal_sphere_exit(vec3 o, vec3 d, float r) {
    float b = dot(o, d);
    float c = dot(o, o) - r * r;
    return -b + sqrt(max(b * b - c, 0.0));
}

// Distance to where the ray enters the sphere from outside, or -1.
float temporal_sphere_entry(vec3 o, vec3 d, float r) {
    float b = dot(o, d);
    float c = dot(o, o) - r * r;
    float h = b * b - c;
    if (h < 0.0) {
        return -1.0;
    }
    return -b - sqrt(h);
}

// Fraction of light that reaches p from direction l, through the rest of the atmosphere.
vec3 temporal_transmittance_to_light(vec3 p, vec3 l) {
    if (temporal_sphere_entry(p, l, TEMPORAL_PLANET_RADIUS) > 0.0) {
        return vec3(0.0);   // behind the planet
    }
    float dt = temporal_sphere_exit(p, l, TEMPORAL_ATMOSPHERE_RADIUS) / float(TEMPORAL_LIGHT_STEPS);
    vec3 depth = vec3(0.0);
    for (int i = 0; i < TEMPORAL_LIGHT_STEPS; i++) {
        depth += temporal_density(length(p + l * ((float(i) + 0.5) * dt)) - TEMPORAL_PLANET_RADIUS) * dt;
    }
    return exp(-temporal_extinction(depth));
}

// Light scattered toward the camera along direction d, from a light in direction l with radiance 1.
// transmittance: how much of what is behind the atmosphere along d gets through (for the sun disc).
vec3 temporal_scattering(vec3 d, vec3 l, float altitude, out vec3 transmittance) {
    vec3 o = vec3(0.0, TEMPORAL_PLANET_RADIUS + altitude, 0.0);
    float rayLength = temporal_sphere_exit(o, d, TEMPORAL_ATMOSPHERE_RADIUS);
    float mu = dot(d, l);
    float phaseRayleigh = 3.0 / (16.0 * TEMPORAL_PI) * (1.0 + mu * mu);
    float g2 = TEMPORAL_MIE_G * TEMPORAL_MIE_G;
    float phaseMie = 3.0 / (8.0 * TEMPORAL_PI) * (1.0 - g2) * (1.0 + mu * mu)
                   / ((2.0 + g2) * pow(1.0 + g2 - 2.0 * TEMPORAL_MIE_G * mu, 1.5));
    vec3 depth = vec3(0.0);
    vec3 sum = vec3(0.0);
    // Steps grow quadratically: dense air near the camera gets most of them.
    for (int i = 0; i < TEMPORAL_VIEW_STEPS; i++) {
        float t0 = rayLength * pow(float(i) / float(TEMPORAL_VIEW_STEPS), 2.0);
        float t1 = rayLength * pow(float(i + 1) / float(TEMPORAL_VIEW_STEPS), 2.0);
        float dt = t1 - t0;
        vec3 p = o + d * (0.5 * (t0 + t1));
        vec3 density = temporal_density(length(p) - TEMPORAL_PLANET_RADIUS);
        vec3 toCamera = exp(-temporal_extinction(depth + density * (0.5 * dt)));
        vec3 scatter = TEMPORAL_RAYLEIGH_SCATTERING * density.x * phaseRayleigh + TEMPORAL_MIE_SCATTERING * density.y * phaseMie;
        sum += toCamera * temporal_transmittance_to_light(p, l) * scatter * dt;
        depth += density * dt;
    }
    transmittance = exp(-temporal_extinction(depth));
    return sum;
}

// Linear radiance of the sky in world direction dir, without the sun disc. The ground below the horizon
// is not modeled: directions below it look at the horizon, darkened.
vec3 temporal_sky(vec3 dir, vec3 sunDirection, float rainBrightness, float altitude, out vec3 transmittance) {
    vec3 d = normalize(vec3(dir.x, max(dir.y, 0.0), dir.z));
    vec3 color = TEMPORAL_NIGHT_GLOW;
    transmittance = vec3(1.0);
    if (sunDirection.y > -0.3) {
        color += temporal_scattering(d, sunDirection, altitude, transmittance) * TEMPORAL_SUN_RADIANCE;
    }
    if (-sunDirection.y > -0.3) {
        vec3 unused;
        color += temporal_scattering(d, -sunDirection, altitude, unused) * TEMPORAL_MOON_RADIANCE;
    }
    color *= mix(1.0, 0.25, smoothstep(0.0, -0.3, dir.y));
    // Rain: a grey, darker overcast sky.
    float luminance = dot(color, vec3(0.2126, 0.7152, 0.0722));
    return mix(color, vec3(luminance * 0.45), (1.0 - rainBrightness) * 0.9);
}

// Linear radiance of the sun disc in direction dir, seen through the atmosphere.
vec3 temporal_sun_disc(vec3 dir, vec3 sunDirection, vec3 transmittance, float rainBrightness) {
    float c = dot(dir, sunDirection);
    if (c < TEMPORAL_SUN_COS_RADIUS - 0.0001 || dir.y < 0.0) {
        return vec3(0.0);
    }
    float edge = smoothstep(TEMPORAL_SUN_COS_RADIUS - 0.0001, TEMPORAL_SUN_COS_RADIUS + 0.00002, c);
    // Limb darkening: the edge of the disc is dimmer than its center.
    float r = sqrt(clamp((1.0 - c) / (1.0 - TEMPORAL_SUN_COS_RADIUS), 0.0, 1.0));
    float limb = 0.4 + 0.6 * sqrt(1.0 - r * r);
    return TEMPORAL_SUN_RADIANCE * 40.0 * transmittance * edge * limb * rainBrightness * rainBrightness;
}

// Height of the camera above the sea, in meters, from its block height: the overworld sea is at y = 63.
float temporal_altitude(float cameraY) {
    return clamp(200.0 + (cameraY - 63.0) * 2.0, 20.0, 4000.0);
}

// ACES filmic curve (Narkowicz 2015), then sRGB-like gamma.
vec3 temporal_tonemap(vec3 linear) {
    vec3 x = linear;
    vec3 mapped = clamp(x * (2.51 * x + 0.03) / (x * (2.43 * x + 0.59) + 0.14), 0.0, 1.0);
    return pow(mapped, vec3(1.0 / 2.2));
}

#endif

#ifndef TEMPORAL_BUS_GLSL
#define TEMPORAL_BUS_GLSL

// Data bus.
//
// Column x = 0 of the screen carries values from core shaders to the post effects. Every program that
// draws the world discards its fragments in that column (TEMPORAL_PROTECT_BUS), and the writers relocate
// their geometry onto a strip of it. The post effects read the values, then paint the column over.
//
// Rows, numbered from NDC y = -1 (the bottom of the screen):
#define TEMPORAL_ROW_MARKER 0      // magenta: the bus was written this frame
#define TEMPORAL_ROW_PROJ 1        // ProjMat, 16 floats, column-major
#define TEMPORAL_ROW_VIEW 17       // view rotation (the sky's ModelViewMat), 16 floats, column-major
#define TEMPORAL_ROW_SKY 33        // sky color (ColorModulator of the sky disc), 3 channels
#define TEMPORAL_ROW_FOG 34        // FogColor
#define TEMPORAL_ROW_FOG_PARAMS 35 // 6 floats: FogEnvironmentalStart, FogEnvironmentalEnd, FogRenderDistanceStart,
                             // FogRenderDistanceEnd, FogSkyEnd, FogCloudsEnd
#define TEMPORAL_SKY_ROWS 41       // rows written by the sky
#define TEMPORAL_ROW_SUN 41        // view-space sun direction (3 components), then the rain brightness mapped to [-1, 1]:
#define TEMPORAL_SUN_ROWS 4        // 24-bit fixed point each
// The sun is drawn with additive blending (color = src * alpha + dst), after the sky: the sky clears the
// sun's rows to black first, so the sum is exactly what the sun writes.
#define TEMPORAL_SKY_STRIP_ROWS 45 // rows covered by the sky's strip: its own values, then the cleared sun rows

// Discard fragments that would land on the bus column. Orthographic renders (the GUI, and the GUI item
// atlas, which core/item draws into) are left alone: they happen elsewhere or after the post effects.
// Needs ProjMat (#include <minecraft:projection.glsl>).
#define TEMPORAL_PROTECT_BUS if (gl_FragCoord.x < 1.0 && ProjMat[2][3] != 0.0) { discard; }
// For full-screen copies onto the world (blit_screen), which have no ProjMat.
#define TEMPORAL_PROTECT_BUS_ALWAYS if (gl_FragCoord.x < 1.0) { discard; }

// A float as 4 bytes (RGBA). Only for writers without blending: the alpha channel is part of the value.
vec4 temporal_pack_float(float v) {
    uint b = floatBitsToUint(v);
    return vec4(float((b >> 24u) & 255u), float((b >> 16u) & 255u), float((b >> 8u) & 255u), float(b & 255u)) / 255.0;
}

float temporal_unpack_float(vec4 c) {
    uvec4 b = uvec4(round(c * 255.0));
    return uintBitsToFloat((b.x << 24u) | (b.y << 16u) | (b.z << 8u) | b.w);
}

// A value in [-1, 1] as 24-bit fixed point in RGB, alpha 1: safe for writers with alpha blending.
vec4 temporal_pack_signed(float v) {
    uint q = uint(round(clamp(v * 0.5 + 0.5, 0.0, 1.0) * 16777215.0));
    return vec4(float((q >> 16u) & 255u), float((q >> 8u) & 255u), float(q & 255u), 255.0) / 255.0;
}

float temporal_unpack_signed(vec4 c) {
    uvec3 b = uvec3(round(c.rgb * 255.0));
    return float((b.x << 16u) | (b.y << 8u) | b.z) / 16777215.0 * 2.0 - 1.0;
}

// Clip-space position of a corner of the strip covering bus rows [firstRow, firstRow + rows).
// corner is (0 or 1, 0 or 1). Corners (0,0), (1,0), (1,1), (0,1) in that order are front-facing.
vec4 temporal_strip_corner(vec2 corner, int firstRow, int rows, vec2 screenSize) {
    vec2 pixel = vec2(corner.x, float(firstRow) + corner.y * float(rows));
    return vec4(-1.0 + 2.0 * pixel / screenSize, 0.0, 1.0);
}

