#ifndef TEMPORAL_FOG_GLSL
#define TEMPORAL_FOG_GLSL

#include <temporal:bus_read.glsl>
#include <temporal:atmosphere.glsl>

// The fog, recomputed in post effects from a pixel's camera-relative position and the fog distances of
// the bus, and the stronger fog the pack uses instead.

float temporal_linear_fog(float distance, float start, float end) {
    return clamp((distance - start) / max(end - start, 1e-3), 0.0, 1.0);
}

// How much of the fog color vanilla mixed in at this position (fog.glsl, for terrain and entities).
float temporal_vanilla_fog(TemporalBus bus, vec3 position) {
    float spherical = length(position);
    float cylindrical = max(length(position.xz), abs(position.y));
    return max(temporal_linear_fog(spherical, bus.fogEnvironmentalStart, bus.fogEnvironmentalEnd),
               temporal_linear_fog(cylindrical, bus.fogRenderDistanceStart, bus.fogRenderDistanceEnd));
}

// How much of the sky the pack mixes in instead, at least vanilla's: a haze that grows with distance
// (aerial perspective), and a softer fade at the edge of the loaded world.
float temporal_fog_amount(TemporalBus bus, vec3 position, float vanillaFog) {
    float cylindrical = max(length(position.xz), abs(position.y));
    float edge = smoothstep(0.5, 0.95, cylindrical / bus.fogRenderDistanceEnd);
    float haze = 1.0 - exp(-length(position) / TEMPORAL_HAZE_DISTANCE);
    return 1.0 - (1.0 - max(vanillaFog, edge)) * (1.0 - haze);
}

#endif

#ifndef TEMPORAL_HAND_GLSL
#define TEMPORAL_HAND_GLSL

// The first-person hand and held items. They are drawn after the world, with their own projection, into the
// world's depth buffer: the post effects can't tell them from the world by depth (they land at 1 to 2 blocks,
// like the ground at one's feet), and they cast screen-space shadows, get occlusion, bloom and trails.
//
// So core/entity and core/item squeeze their depth into the thousandth next to the near plane (depth is
// reversed: 1 is near), keeping their order, where nothing of the world can be (closer than 0.05 block).
// The post effects then leave those pixels out. Tagging them in alpha doesn't work: the player's skin is drawn
// with a translucent pipeline, whose blending adds part of the alpha behind.
//
// A hand vertex is within 1.5 blocks of the eye, with a perspective projection (GUI items are orthographic):
// world entities never get that close, except a mob pressed against the camera.

bool temporal_is_hand_vertex(vec3 position, mat4 projection) {
    return projection[2][3] != 0.0 && dot(position, position) < 2.25;
}

// Normalized device depth (1 near; down to -1 on OpenGL, 0 on Vulkan) squeezed against the near plane.
float temporal_hand_depth(float ndcDepth) {
    return 1.0 - (1.0 - ndcDepth) * 0.001;
}

// From the depth buffer (0 to 1 on both backends).
bool temporal_is_hand(float depth) {
    return depth > 0.9985;
}

