#ifndef TEMPORAL_LIGHT_CODE_GLSL
#define TEMPORAL_LIGHT_CODE_GLSL

// Light levels in the alpha of opaque terrain (solid and cutout blocks), for the post effects.
//
// The alpha of minecraft:main then has three ranges:
//   0 to 204:   translucent things in front of the clear color: clouds (at most 0.8), far water, glass;
//   205 to 252: opaque terrain, with 8 sky light levels x 6 block light levels;
//   255:        anything else that is opaque (entities, block entities…), left as it is.

// levels: (block, sky), each 0 to 1 (light level / 15).
float temporal_encode_light(vec2 levels) {
    float sky = round(clamp(levels.y, 0.0, 1.0) * 7.0);
    float block = round(clamp(levels.x, 0.0, 1.0) * 5.0);
    return (205.0 + sky * 6.0 + block) / 255.0;
}

bool temporal_decode_light(float alpha, out vec2 levels) {
    float v = round(alpha * 255.0) - 205.0;
    levels = vec2(mod(v, 6.0) / 5.0, floor(v / 6.0) / 7.0);
    return v >= 0.0 && v <= 47.0;
}

