#ifndef TEMPORAL_LIGHTING_GLSL
#define TEMPORAL_LIGHTING_GLSL

// Relighting opaque terrain. The vanilla image already holds albedo x light, and only the light levels are
// known, so the pack changes the light by a factor instead of computing it from scratch:
//
//   factor = (light from the sky the pack wants) / (light from the sky vanilla gave)
//
// mixed with 1 by the share of sky light in the pixel (block light is left alone). Vanilla's sky light is
// uniform but for a fixed shade per face (CardinalLighting.DEFAULT: up 1, down 0.5, north and south 0.8,
// east and west 0.6). The pack's is an ambient sky light, brighter on faces that see more sky, plus a direct
// light from the sun (the moon by night) along the face's normal. Both are normalized so that a face
// pointing up keeps vanilla's brightness: the overall level of day and night stays vanilla's, only the
// direction and the color change.

const float TEMPORAL_DIRECT_SHARE = 0.45;   // share of the direct light on a face that faces it, by day
const float TEMPORAL_MOON_SHARE = 0.3;      // the same, by night
const float TEMPORAL_AMBIENT_TINT = 0.3;    // how much of the sky's color the ambient light keeps (0: white)
const float TEMPORAL_DIRECT_TINT = 0.7;     // the same for the direct light (orange at sunset)

// Vanilla's light curve for a level from 0 to 1 (the lightmap's brightness, before gamma).
float temporal_light_curve(float level) {
    return level / (4.0 - 3.0 * level);
}

// shadow: 1 where the direct light reaches the surface, 0 where something stands in the way (temporal:shadows.glsl).
vec3 temporal_relight(vec3 faceNormal, vec2 levels, vec3 sunDirection, float rainBrightness, vec3 ambientColor, vec3 directColor, float shadow) {
    // The face's axis: the normal from depth derivatives is exact on flat faces, noisy on edges.
    // Surfaces that face no axis are plants (two diagonal quads, which vanilla doesn't shade) or block
    // edges: they keep vanilla's brightness, and only take the light's color.
    vec3 m = abs(faceNormal);
    vec3 n;
    float vanillaShade;
    if (max(m.x, max(m.y, m.z)) < 0.9) {
        n = vec3(0.0, 1.0, 0.0);
        vanillaShade = 1.0;
    } else if (m.y >= m.x && m.y >= m.z) {
        n = vec3(0.0, sign(faceNormal.y), 0.0);
        vanillaShade = faceNormal.y > 0.0 ? 1.0 : 0.5;
    } else if (m.z >= m.x) {
        n = vec3(0.0, 0.0, sign(faceNormal.z));
        vanillaShade = 0.8;
    } else {
        n = vec3(sign(faceNormal.x), 0.0, 0.0);
        vanillaShade = 0.6;
    }

    // Light colors with a luminance of 1, partly desaturated: a fully blue sky light turns sand blue.
    const vec3 luma = vec3(0.2126, 0.7152, 0.0722);
    ambientColor = mix(vec3(1.0), ambientColor / max(dot(ambientColor, luma), 1e-3), TEMPORAL_AMBIENT_TINT);
    directColor = mix(vec3(1.0), directColor / max(dot(directColor, luma), 1e-3), TEMPORAL_DIRECT_TINT);

    bool day = sunDirection.y > 0.0;
    vec3 l = day ? sunDirection : -sunDirection;
    float direct = (day ? TEMPORAL_DIRECT_SHARE : TEMPORAL_MOON_SHARE) * smoothstep(0.0, 0.15, l.y) * rainBrightness * rainBrightness;
    vec3 ambient = ambientColor * (1.0 - direct);
    vec3 light = ambient * (0.8 + 0.2 * n.y) + directColor * direct * max(dot(n, l), 0.0) * shadow;   // sides see less sky
    vec3 up = ambient + directColor * direct * l.y;
    vec3 skyFactor = light / max(dot(up, luma), 1e-3) / vanillaShade;
    skyFactor = clamp(skyFactor, vec3(0.3), vec3(1.6));

    // Share of the sky in the pixel's light. Vanilla dims sky light at night, not block light.
    float daylight = mix(0.25, 1.0, smoothstep(-0.2, 0.2, sunDirection.y));
    float sky = temporal_light_curve(levels.y) * daylight;
    float share = sky / max(sky + temporal_light_curve(levels.x), 1e-3);
    return mix(vec3(1.0), skyFactor, share);
}

// Light on the clouds, as a factor on vanilla's cloud color (which already follows the time of day): the
// color of the light (warm at sunset, from the sun through the air), and forward scattering, the bright rim of
// a cloud seen toward the sun (Henyey-Greenstein-like lobe).
const float TEMPORAL_CLOUD_TINT = 0.6;
const float TEMPORAL_CLOUD_SILVER = 0.55;

vec3 temporal_cloud_light(vec3 viewDir, vec3 sunDirection, float rainBrightness, vec3 ambientColor, vec3 directColor) {
    const vec3 luma = vec3(0.2126, 0.7152, 0.0722);
    float day = smoothstep(-0.1, 0.1, sunDirection.y);
    vec3 direct = directColor / max(dot(directColor, luma), 1e-3);
    vec3 ambient = ambientColor / max(dot(ambientColor, luma), 1e-3);
    vec3 tint = mix(vec3(1.0), mix(ambient, direct, 0.6 * day), TEMPORAL_CLOUD_TINT);
    float forward = pow(max(dot(viewDir, sunDirection), 0.0), 8.0);
    return tint * (1.0 + TEMPORAL_CLOUD_SILVER * forward * day * rainBrightness);
}

#endif

#ifndef TEMPORAL_SHADOWS_GLSL
#define TEMPORAL_SHADOWS_GLSL

#include <temporal:bus_read.glsl>
#include <temporal:hand.glsl>

// Screen-space shadows: from a point, march toward the light in view space, and check at each step whether
// the depth buffer has something in front of the ray. Only what is on screen can cast a shadow, and only
// within about 28 blocks.

// Steps start short and grow by 15 %, up to 0.3 block: 96 steps reach about 28 blocks.
#define TEMPORAL_SHADOW_STEPS 96
const float TEMPORAL_SHADOW_FIRST_STEP = 0.05;
const float TEMPORAL_SHADOW_MAX_STEP = 0.3;
// How far behind the visible surface, in blocks, the ray counts as blocked. The camera only sees the front
// of an occluder, and a ray through its back half is up to about 1.7 blocks behind that front, for a block
// seen at an angle. The window must be longer than that by at least two steps, or whether a ray counts as
// blocked depends on where its samples fall, and the edge of the shadow becomes a comb. Much longer, and
// rays that only pass behind an occluder count as blocked too.
const float TEMPORAL_SHADOW_THICKNESS = 2.2;
const float TEMPORAL_SHADOW_FADE_START = 64.0;    // distance from the camera where shadows start to fade out
const float TEMPORAL_SHADOW_FADE_END = 96.0;

// A per-pixel offset in [0, 1) (interleaved gradient noise, Jimenez 2014), to turn banding into fine noise.
float temporal_shadow_jitter(vec2 pixel) {
    return fract(52.9829189 * fract(dot(pixel, vec2(0.06711056, 0.00583715))));
}

// 1: lit, 0: in shadow. viewPosition: the point, in view space; viewLight: the direction to the light, in
// view space; viewNormal: the surface normal, in view space (the ray starts a little off the surface).
// The first-person hand casts no shadow (temporal:hand.glsl).
float temporal_screen_shadow(TemporalBus bus, sampler2D depthSampler, vec3 viewPosition, vec3 viewNormal, vec3 viewLight, vec2 pixel) {
    float distance = length(viewPosition);
    if (distance > TEMPORAL_SHADOW_FADE_END) {
        return 1.0;
    }
    float stepLength = TEMPORAL_SHADOW_FIRST_STEP * (1.0 + 0.01 * distance);
    float thickness = TEMPORAL_SHADOW_THICKNESS + 0.02 * distance;   // depth gets coarser with distance
    vec3 position = viewPosition + viewNormal * (0.02 + 0.002 * distance)
                  + viewLight * stepLength * temporal_shadow_jitter(pixel);
    float shadow = 0.0;
    for (int i = 0; i < TEMPORAL_SHADOW_STEPS; i++) {
        position += viewLight * stepLength;
        stepLength = min(stepLength * 1.15, TEMPORAL_SHADOW_MAX_STEP);
        vec4 clip = bus.proj * vec4(position, 1.0);
        if (clip.w <= 0.0) {
            break;
        }
        vec2 uv = clip.xy / clip.w * 0.5 + 0.5;
        if (any(lessThan(uv, vec2(0.0))) || any(greaterThan(uv, vec2(1.0)))) {
            break;   // off screen: nothing known there, assume lit
        }
        float depth = texture(depthSampler, uv).r;
        if (depth <= 0.0 || temporal_is_hand(depth)) {
            continue;   // sky, or the hand
        }
        // > 0: the scene there is closer to the camera than the ray, so the ray passes behind it.
        float behind = temporal_view_position(bus, uv, depth).z - position.z;
        if (behind > 0.01) {
            // Fully blocked well inside the window, fading out toward its end: a hard limit makes the edge
            // of the shadow depend on where each ray's samples fall, a comb.
            shadow = max(shadow, 1.0 - smoothstep(0.6 * thickness, thickness, behind));
            if (shadow >= 1.0) {
                break;
            }
        }
    }
    return 1.0 - shadow * (1.0 - smoothstep(TEMPORAL_SHADOW_FADE_START, TEMPORAL_SHADOW_FADE_END, distance));
}

#endif

#ifndef TEMPORAL_WATER_GLSL
#define TEMPORAL_WATER_GLSL

// Water markers. The terrain shaders (vanilla and Sodium) recognize water fragments, and on every even
// screen column write a marker instead of the water color, with alpha 1 so that blending keeps it exact.
// Odd columns keep the vanilla water, blended over what is underneath: the post effects take the
// refraction color from them, and redraw the surface.
//
// Water textures (water_still, water_flow, water_overlay) have a uniform alpha of 180/255. The slime block
// shares it, but water is tinted by the biome and slime is not.
#define TEMPORAL_WATER_ALPHA 180.0

bool temporal_is_water(vec4 textureColor, vec4 tint) {
    return abs(textureColor.a * 255.0 - TEMPORAL_WATER_ALPHA) < 0.5
        && max(tint.r, max(tint.g, tint.b)) - min(tint.r, min(tint.g, tint.b)) > 0.05;
}

// The marker of column x: two bytes that depend on x, so that a scene color matches by chance with a
// probability of 1 in 65536 per pixel, and only where it is also at the right place. Only x is used:
// gl_FragCoord.y doesn't count from the same edge on every backend. The third byte carries data.
vec4 temporal_water_marker(int x, float data) {
    return vec4(float((x * 73 + 11) & 255) / 255.0, float((x * 197 + 89) & 255) / 255.0, data, 1.0);
}

// Two bytes alone are not enough: a uniform color filling whole columns (the clear color under water, where the
// sky isn't drawn) matches the marker of one of the ~850 even columns about once in 77, and that column became a
// vertical stripe. So a marker also has alpha 1 and a valid data byte (0.5 or 1); the caller also checks that
// something was drawn there (depth > 0).
bool temporal_is_water_marker(vec4 c, int x) {
    vec4 m = temporal_water_marker(x, 0.0);
    bool data = abs(c.b - 1.0) < 0.5 / 255.0 || abs(c.b - 128.0 / 255.0) < 1.0 / 255.0;
    return (x & 1) == 0 && abs(c.r - m.r) < 0.5 / 255.0 && abs(c.g - m.g) < 0.5 / 255.0
        && c.a > 254.5 / 255.0 && data;
}

// The data byte: 1 for a horizontal surface (the top of water, or its bottom seen from below), 0.5 for a side.
float temporal_water_data(vec3 cameraRelativePosition) {
    vec3 n = normalize(cross(dFdx(cameraRelativePosition), dFdy(cameraRelativePosition)));
    return abs(n.y) > 0.7 ? 1.0 : 0.5;
}

#endif

#ifndef TEMPORAL_WIND_GLSL
#define TEMPORAL_WIND_GLSL

// Waving plants, for core/terrain.vsh. Plants are recognized from what a vertex shader has: they are in the
// cutout layer (ALPHA_CUTOUT 0.5), tinted by the biome (grass, ferns, tall grass, sugar cane, vines), and off
// the block grid (cross models are inset by a pixel, vines stand off the wall; the grass block, also tinted
// and cutout, is on the grid and must not move, or the ground would crack).
//
// Under Sodium, Sodium's terrain shader does the same (patches/assets/sodium/), with its own clock.
//
// A vertex can't tell the top of a plant from its base: vertex indices change from run to run and between
// backends, UV0 lies on sprite corners, shared with the neighbouring sprites in the atlas, and both ends are at
// whole block heights. So the whole plant sways, a little, and the phase of the wind changes with height, so
// that a plant's top and base don't move together: it bends more than it slides.

const float TEMPORAL_WIND_AMPLITUDE = 0.045;   // blocks

bool temporal_is_plant(vec3 worldPosition, vec4 tint) {
    vec2 f = fract(worldPosition.xz);
    bool offGrid = any(greaterThan(min(f, 1.0 - f), vec2(0.01)));
    bool tinted = max(tint.r, max(tint.g, tint.b)) - min(tint.r, min(tint.g, tint.b)) > 0.05;
    return offGrid && tinted;
}

// The wind's offset (x, z) at a world position. time goes from 0 to 1 every 1200 s, and every frequency is a
// whole number of cycles per wrap, so the plants don't jump when it wraps. In core/terrain it is GameTime.
// Sodium's terrain shader has no GameTime, but u_CurrentTime, the milliseconds since its region (8 x 4 x 8
// sections) was created: temporal_wind_time_sodium turns it into the same kind of clock. It starts at a different
// moment in each region, which only shifts the phase of the wind there: plants on either side of a region's
// border don't touch, so it doesn't show.
vec2 temporal_wind(vec3 p, float gameTime) {
    const float TAU = 6.28318531;
    float gust = 0.6 + 0.4 * sin(TAU * gameTime * 37.0 + p.x * 0.11 + p.z * 0.07);
    float x = sin(TAU * gameTime * 520.0 + p.x * 0.8 + p.z * 0.3 + p.y * 1.7)
            + 0.4 * sin(TAU * gameTime * 1130.0 + p.x * 2.1 - p.y * 2.3);
    float z = sin(TAU * gameTime * 470.0 + p.z * 0.9 - p.x * 0.2 + p.y * 1.9)
            + 0.4 * sin(TAU * gameTime * 1270.0 + p.z * 2.4 + p.y * 2.1);
    return TEMPORAL_WIND_AMPLITUDE * gust * vec2(x, z) / 1.4;
}

float temporal_wind_time_sodium(int currentTimeMs) {
    return float(currentTimeMs % 1200000) / 1200000.0;
}

