// The glow is a fixed fan of 18 vertices (SkyRenderer): the center at (0, 100, 0), then a ring at
// (120 sin a, 120 cos a, -40 cos a). Debug shapes, the other users of this program, don't match it.
bool isSunriseFan() {
    if (ProjMat[2][3] == 0.0 || gl_VertexIndex >= 18) {
        return false;
    }
    if (gl_VertexIndex == 0) {
        return distance(Position, vec3(0.0, 100.0, 0.0)) < 0.01;
    }
    return abs(length(Position.xy) - 120.0) < 0.01 && abs(Position.z + Position.y / 3.0) < 0.01;
}

void main() {
    gl_Position = ProjMat * ModelViewMat * vec4(Position, 1.0);
    if (isSunriseFan()) {
        gl_Position = vec4(2.0, 2.0, 0.0, 1.0);   // outside the screen: nothing drawn
    }

