void main() {
    // The celestial pipeline blends additively: RGB fixed point, alpha 1, on rows the sky cleared to black.
    if (isSun == 1) {
        int k = int(floor(busRow)) - TEMPORAL_ROW_SUN;
        fragColor = temporal_pack_signed(sunData[clamp(k, 0, 3)]);
