texCoord0 = UV0;

// The sun and the moon both use this program. The sun quad is scaled by 30, the moon's by 20.
isSun = abs(length(ModelViewMat[0].xyz) - 30.0) < 1.0 ? 1 : 0;
busRow = 0.0;
// Direction of the sun's center, in view space (the quad is centered on its local origin), and the rain
// brightness, which the game passes as the alpha of ColorModulator (1: clear, 0: full rain).
sunData = vec4(normalize((ModelViewMat * vec4(0.0, 0.0, 0.0, 1.0)).xyz), ColorModulator.a * 2.0 - 1.0);
if (isSun == 1) {
    int k = gl_VertexIndex % 4;
    vec2 corner = vec2(k == 1 || k == 2 ? 1.0 : 0.0, k == 2 || k == 3 ? 1.0 : 0.0);
    gl_Position = temporal_strip_corner(corner, TEMPORAL_ROW_SUN, TEMPORAL_SUN_ROWS, ScreenSize);
    busRow = float(TEMPORAL_ROW_SUN) + corner.y * float(TEMPORAL_SUN_ROWS);
}

int row = int(floor(busRow));
if (row == TEMPORAL_ROW_MARKER) {
    fragColor = vec4(1.0, 0.0, 1.0, 1.0);
} else if (row < TEMPORAL_ROW_VIEW) {
    int k = row - TEMPORAL_ROW_PROJ;
    fragColor = temporal_pack_float(ProjMat[k / 4][k % 4]);
} else if (row < TEMPORAL_ROW_SKY) {
    int k = row - TEMPORAL_ROW_VIEW;
    fragColor = temporal_pack_float(ModelViewMat[k / 4][k % 4]);
} else if (row == TEMPORAL_ROW_SKY) {
    fragColor = vec4(ColorModulator.rgb, 1.0);
} else if (row == TEMPORAL_ROW_FOG) {
    fragColor = vec4(FogColor.rgb, 1.0);
} else if (row < TEMPORAL_SKY_ROWS) {
